BEGIN;
CREATE TABLE IF NOT EXISTS bi_report_definitions(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,data_source TEXT NOT NULL,description TEXT,selected_fields JSONB NOT NULL DEFAULT '[]',filters JSONB NOT NULL DEFAULT '[]',grouping JSONB NOT NULL DEFAULT '[]',sorting JSONB NOT NULL DEFAULT '[]',formula_fields JSONB NOT NULL DEFAULT '[]',aggregations JSONB NOT NULL DEFAULT '[]',pivot_config JSONB NOT NULL DEFAULT '{}',chart_config JSONB NOT NULL DEFAULT '{}',is_system BOOLEAN DEFAULT FALSE,is_active BOOLEAN DEFAULT TRUE,created_by INTEGER REFERENCES users(id),updated_by INTEGER REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS bi_dashboards(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT,is_default BOOLEAN DEFAULT FALSE,is_shared BOOLEAN DEFAULT FALSE,owner_id INTEGER REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS bi_dashboard_widgets(id BIGSERIAL PRIMARY KEY,dashboard_id BIGINT NOT NULL REFERENCES bi_dashboards(id) ON DELETE CASCADE,report_id BIGINT REFERENCES bi_report_definitions(id) ON DELETE SET NULL,title TEXT NOT NULL,widget_type TEXT NOT NULL CHECK(widget_type IN('KPI Card','Table','Bar Chart','Line Chart','Pie Chart','Donut Chart','Heat Map','Trend Chart','Gauge Chart')),configuration JSONB NOT NULL DEFAULT '{}',position INTEGER DEFAULT 0,width INTEGER DEFAULT 1,height INTEGER DEFAULT 1,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS bi_report_schedules(id BIGSERIAL PRIMARY KEY,report_id BIGINT REFERENCES bi_report_definitions(id) ON DELETE CASCADE,name TEXT NOT NULL,frequency TEXT NOT NULL DEFAULT 'Monthly',day_of_month INTEGER DEFAULT 1,delivery_time TIME DEFAULT '09:00',timezone TEXT DEFAULT 'Asia/Kolkata',recipients JSONB NOT NULL DEFAULT '[]',export_format TEXT DEFAULT 'xlsx',is_active BOOLEAN DEFAULT TRUE,last_run_at TIMESTAMPTZ,next_run_at TIMESTAMPTZ,created_by INTEGER REFERENCES users(id),created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS bi_report_runs(id BIGSERIAL PRIMARY KEY,report_id BIGINT REFERENCES bi_report_definitions(id) ON DELETE SET NULL,schedule_id BIGINT REFERENCES bi_report_schedules(id) ON DELETE SET NULL,status TEXT NOT NULL,format TEXT,row_count INTEGER DEFAULT 0,details TEXT,run_by INTEGER REFERENCES users(id),started_at TIMESTAMPTZ DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS bi_drill_paths(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,data_source TEXT NOT NULL,levels JSONB NOT NULL,created_at TIMESTAMPTZ DEFAULT now());
INSERT INTO bi_drill_paths(name,data_source,levels)VALUES('Revenue Drill Down','finance','["state","buyer_name","order_number","buyer_invoice_number","commercial_number"]'::jsonb)ON CONFLICT(name)DO NOTHING;
INSERT INTO bi_dashboards(name,description,is_default,is_shared)SELECT 'Executive Business Dashboard','Cross-functional Sales, Procurement, Logistics, Finance and Customer intelligence',TRUE,TRUE WHERE NOT EXISTS(SELECT 1 FROM bi_dashboards WHERE is_default);
UPDATE roles SET permissions=jsonb_set(COALESCE(permissions,'{}'::jsonb),'{modules,reports}','true'::jsonb,true);
COMMIT;
